mapper.select:
SELECT
#{statDate} AS statDate,

(SELECT COUNT(*) FROM `user`
WHERE DATE(created_at) <= #{statDate}
) AS totalUsers,

(SELECT COUNT(*) FROM `user`
WHERE DATE(created_at) = #{statDate}
) AS newUsers,

(SELECT COUNT(DISTINCT user_id) FROM operation_log
WHERE DATE(created_at) = #{statDate}
) AS activeUsers,

(SELECT COUNT(*) FROM document
WHERE DATE(created_at) <= #{statDate} AND deleted_at IS NULL
) AS totalNotes,

(SELECT COUNT(*) FROM document
WHERE DATE(created_at) = #{statDate} AND deleted_at IS NULL
) AS newNotes,

(SELECT COUNT(*) FROM knowledge_base
WHERE DATE(created_at) <= #{statDate} AND deleted = 0
) AS totalKbs,

(SELECT COUNT(*) FROM knowledge_base
WHERE DATE(created_at) = #{statDate} AND deleted = 0
) AS newKbs,

(SELECT COUNT(*) FROM comment
WHERE DATE(created_at) <= #{statDate}
) AS totalComments
